// Give it a String() method so it prints readably instead of as a number:
func (s Status) String() string {
    switch s {
    case StatusPending:
        return "pending"
    case StatusActive:
        return "active"
    case StatusSuspended:
        return "suspended"
    case StatusClosed:
        return "closed"
    default:
        return "unknown"
    }
